node -e "
const fs=require('fs');
const j=JSON.parse(fs.readFileSync('artifacts/wdi-tfr-raw.json','utf8'));
const rows=j[1]||[];
const by={};
for (const r of rows) {
  if (!r || r.value==null) continue;
  const c=r.countryiso3code;
  if (!by[c] || r.date>by[c].year) by[c]={iso3:c,name:r.country.value,year:+r.date,tfr:+r.value};
}
console.log(JSON.stringify(Object.values(by).sort((a,b)=>a.name.localeCompare(b.name)),null,2));
"

