curl -sL "https://api.worldbank.org/v2/country/all/indicator/SP.DYN.TFRT.IN?format=json&date=2022&per_page=400" -o artifacts/wdi-tfr-all.json
node -e "
const fs=require('fs');
const j=JSON.parse(fs.readFileSync('artifacts/wdi-tfr-all.json','utf8'));
console.log(j[0]);
const want=new Set(['AUS','AUT','BEL','CAN','CHE','CHL','CZE','DEU','DNK','ESP','EST','FIN','FRA','GBR','GRC','HUN','IRL','ISL','ISR','ITA','JPN','KOR','LTU','LUX','LVA','MEX','NLD','NOR','NZL','POL','PRT','SVK','SVN','SWE','TUR','USA','OECD']);
const out=[];
for (const r of j[1]||[]) {
  if (!r || r.value==null) continue;
  if (!want.has(r.countryiso3code)) continue;
  out.push({iso3:r.countryiso3code,name:r.country.value,year:+r.date,tfr:+r.value});
}
out.sort((a,b)=>a.name.localeCompare(b.name));
console.log(JSON.stringify(out,null,2));
fs.writeFileSync('artifacts/wdi-tfr-oecd.json', JSON.stringify(out,null,2));
"

