args.command:
node -e "
const fs=require('fs');
const j=JSON.parse(fs.readFileSync('artifacts/oecd-ncc-2022.json','utf8'));
const dims=j.data.structures[0].dimensions.series;
const idx = Object.fromEntries(dims.map((d,i)=>[d.id,i]));
function find(dimId, code){ return dims[idx[dimId]].values.findIndex(v=>v.id===code); }
const series=j.data.dataSets[0].series;
const areas=dims[idx.REF_AREA].values;
function extract(cost){
  const want={MEASURE:0, UNIT:0, CURR:2, HH:1, AGE:0, PART:2, USE:0, SOC:0, HOUSE:0, COST:find('CHILDCARE_COST',cost), FREQ:0};
  const out={};
  for(let ai=0;ai<areas.length;ai++){
    const key=[ai,want.MEASURE,want.UNIT,want.CURR,want.HH,want.AGE,want.PART,want.USE,want.SOC,want.HOUSE,want.COST,want.FREQ].join(':');
    const s=series[key]; if(!s) continue; const v=s.observations['0']?.[0]; if(v==null) continue;
    out[areas[ai].id]=Math.round(v*10)/10;
  }
  return out;
}
const net=extract('_T'), fee=extract('CF'), ben=extract('CB'), tax=extract('TAX'), oth=extract('_O');
// single
function extractS(){
  const want={MEASURE:0, UNIT:0, CURR:1, HH:0, AGE:0, PART:0, USE:0, SOC:0, HOUSE:0, COST:3, FREQ:0};
  const out={};
  for(let ai=0;ai<areas.length;ai++){
    const key=[ai,want.MEASURE,want.UNIT,want.CURR,want.HH,want.AGE,want.PART,want.USE,want.SOC,want.HOUSE,want.COST,want.FREQ].join(':');
    const s=series[key]; if(!s) continue; const v=s.observations['0']?.[0]; if(v==null) continue;
    out[areas[ai].id]=Math.round(v*10)/10;
  }
  return out;
}
const single=extractS();
const isos=['NZL','USA','CAN','IRL','GBR','AUS','NLD','CHE','CZE','BEL','FIN','ISR','SVK','FRA','DNK','JPN','ESP','SVN','GRC','LUX','POL','LTU','NOR','HUN','SWE','KOR','PRT','ISL','EST','AUT','DEU','ITA','LVA'];
for (const iso of isos) {
  const n=net[iso],f=fee[iso],b=ben[iso],t=tax[iso],o=oth[iso],s=single[iso];
  const sum=(f||0)+(b||0)+(t||0)+(o||0);
  console.log(JSON.stringify({iso,n,f,b,t,o,s,sum,ok:Math.abs(sum-n)<0.2}));
}
"

