const series=j.data.dataSets[0].series;
const areas=dims[idx.REF_AREA].values;
function extract(hh,curr,part,cost){
  const want={MEASURE:0, UNIT:0, CURR:find('INCOME_CURR',curr), HH:find('HOUSEHOLD_TYPE',hh), AGE:0, PART:find('INCOME_PART',part), USE:0, SOC:0, HOUSE:0, COST:find('CHILDCARE_COST',cost), FREQ:0};
