const rows=[];
for (const iso of Object.keys(names)) {
  if (net[iso]==null || !tfr[iso]) continue;
  rows.push({iso3:iso,name:names[iso],region:region[iso],netCostPctAW:net[iso],feePctAW:fee[iso]??null,benefitPctAW:ben[iso]??null,taxPctAW:tax[iso]??null,otherPctAW:oth[iso]??null,singleNetCostPctAW:single[iso]??null,tfr:tfr[iso].tfr,tfrYear:tfr[iso].year});
