rows.sort((a,b)=>b.netCostPctAW-a.netCostPctAW || a.name.localeCompare(b.name));
let out='export const COUNTRIES: CountryRow[] = '+JSON.stringify(rows,null,2).replace(/\"([a-zA-Z0-9_]+)\":/g,'\$1:')+';\\n';
fs.writeFileSync('artifacts/countries-export.ts', out);
console.log('wrote', rows.length);
"

