import fs from "node:fs";

const j = JSON.parse(fs.readFileSync("artifacts/oecd-ncc-2022.json", "utf8"));
const dims = j.data.structures[0].dimensions.series;
const idx = Object.fromEntries(dims.map((d, i) => [d.id, i]));
function find(dimId, code) {
  return dims[idx[dimId]].values.findIndex((v) => v.id === code);
}
const series = j.data.dataSets[0].series;
const areas = dims[idx.REF_AREA].values;

function extract(hh, curr, part, cost) {
  const want = {
    MEASURE: 0,
    UNIT: 0,
    CURR: find("INCOME_CURR", curr),
    HH: find("HOUSEHOLD_TYPE", hh),
    AGE: 0,
    PART: find("INCOME_PART", part),
    USE: 0,
    SOC: 0,
    HOUSE: 0,
    COST: find("CHILDCARE_COST", cost),
    FREQ: 0,
  };
  const out = {};
  for (let ai = 0; ai < areas.length; ai++) {
    const key = [
      ai,
      want.MEASURE,
      want.UNIT,
      want.CURR,
      want.HH,
      want.AGE,
      want.PART,
      want.USE,
      want.SOC,
      want.HOUSE,
      want.COST,
      want.FREQ,
    ].join(":");
    const s = series[key];
    if (!s) continue;
    const v = s.observations["0"]?.[0];
    if (v == null) continue;
    out[areas[ai].id] = Math.round(v * 10) / 10;
  }
  return out;
}

const net = extract("C_C2", "AW100", "AW67", "_T");
const fee = extract("C_C2", "AW100", "AW67", "CF");
const ben = extract("C_C2", "AW100", "AW67", "CB");
const tax = extract("C_C2", "AW100", "AW67", "TAX");
const oth = extract("C_C2", "AW100", "AW67", "_O");
const single = extract("S_C2", "AW67", "_Z", "_T");
const tfr = Object.fromEntries(
  JSON.parse(fs.readFileSync("artifacts/wdi-tfr-oecd.json", "utf8")).map((r) => [
    r.iso3,
    r,
  ]),
);

const region = {
  AUS: "Anglosphere",
  CAN: "Anglosphere",
  IRL: "Anglosphere",
