import fs from "node:fs";

const rows = JSON.parse(
  fs.readFileSync("artifacts/countries-verified.json", "utf8"),
);

function pearson(pts) {
  const xs = pts.map((p) => p.netCostPctAW);
  const ys = pts.map((p) => p.tfr);
  const n = xs.length;
  const mx = xs.reduce((a, b) => a + b, 0) / n;
  const my = ys.reduce((a, b) => a + b, 0) / n;
  let num = 0;
  let dx = 0;
  let dy = 0;
  for (let i = 0; i < n; i++) {
    num += (xs[i] - mx) * (ys[i] - my);
    dx += (xs[i] - mx) ** 2;
    dy += (ys[i] - my) ** 2;
  }
  return Math.round((num / Math.sqrt(dx * dy)) * 1000) / 1000;
}

function mean(arr, k) {
  return Math.round((arr.reduce((s, x) => s + x[k], 0) / arr.length) * 1000) / 1000;
}

const rAll = pearson(rows);
const rNo = pearson(rows.filter((r) => r.iso3 !== "ISR" && r.iso3 !== "KOR"));
const low = rows.filter((r) => r.netCostPctAW < 8);
