const NAVY = "#0f172a";
const TEAL = "#0f766e";
const AMBER = "#d97706";
const ROSE = "#e11d48";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
