                  />
                  <Bar dataKey="meanTfr" name="Mean TFR" radius={[6, 6, 0, 0]}>
                    {regionBars.map((r) => (
                      <Cell key={r.region} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      ) : null}

      {view === "decomp" ? (
        <ChartCard
          title="Fee vs benefit decomposition"
          subtitle="Selected countries: gross fee, benefit offset (absolute), and net cost (% AW)"
