          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={decomp}
                margin={{ top: 8, right: 12, bottom: 48, left: 0 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="name"
                  interval={0}
                  angle={-28}
                  textAnchor="end"
                  height={60}
                  tick={{ fontSize: 10, fill: "#64748b" }}
                />
                <YAxis tick={{ fontSize: 11, fill: "#64748b" }} />
                <Tooltip />
                <Legend />
                <Bar dataKey="fee" name="Gross fee" fill={ROSE} />
                <Bar
                  dataKey="benefitAbs"
                  name="Benefit offset (|%|)"
                  fill={TEAL}
                />
                <Bar dataKey="net" name="Net cost" fill={NAVY} />
              </BarChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Italy and Korea show large gross fees nearly fully offset by
            benefits; New Zealand and the US keep high net costs after support.
          </p>
        </ChartCard>
      ) : null}

      <details className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
        <summary className="cursor-pointer font-medium text-slate-800">
          Sources & method note
        </summary>
        <ul className="mt-2 list-disc space-y-1 pl-5">
          {SOURCES.map((s) => (
            <li key={s}>{s}</li>
          ))}
        </ul>
        <p className="mt-2 text-xs leading-relaxed text-slate-500">
          {SOURCE_NOTE}
        </p>
        <p className="mt-1 text-xs text-slate-400">
          Sample size {COUNTRIES.length}; OECD average dual-earner net cost{" "}
          {HEADLINE.oecdAvgNetCostPctAW}% AW ({HEADLINE.year}).
        </p>
      </details>
    </div>
  );
}

