                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Showing {scatterData.length} countries
              {outliers === "excl" ? " (Israel and Korea removed)" : ""}.
              Colors = region. Full-sample dual-earner Pearson r ={" "}
