                  />
                  <Tooltip />
                  <Bar dataKey="meanTfr" name="Mean TFR" radius={[6, 6, 0, 0]}>
                    {bandBars.map((b) => (
                      <Cell
                        key={b.band}
                        fill={
                          b.band.startsWith("Under")
                            ? TEAL
                            : b.band.startsWith("20")
                              ? ROSE
                              : AMBER
                        }
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Low-cost band mean TFR {HEADLINE.lowCostMeanTfr} vs high-cost{" "}
              {HEADLINE.highCostMeanTfr} ??? opposite a simple ???cheap care, more
              babies??? cross-section story.
            </p>
          </ChartCard>
        </div>
      ) : null}

      {view === "bands" ? (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Mean TFR and mean cost by band"
