                  />
                  <YAxis
                    yAxisId="cost"
                    orientation="right"
                    domain={[0, 30]}
                    tick={{ fontSize: 11, fill: "#64748b" }}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    yAxisId="tfr"
