// Ensure data helpers have the names the dashboard expects
let data = fs.readFileSync(dataPath, "utf8");
if (!data.includes("export function countriesByRegion")) {
  data = data.replace(
    "export function countriesByRegion",
    "export function countriesByRegion",
  );
}
// Add aliases at end if missing
if (!data.includes("export const countriesByRegion =")) {
  data += `

/** Aliases for dashboard imports */
export const countriesByRegion = countriesByRegion;
export const decompositionRows = decompositionRows;
`;
}
// Fix COST_BANDS label if still broken
data = data.replace(/label: "8"19% AW"/, 'label: "8-19% AW"');
fs.writeFileSync(dataPath, data);

// Rewrite dashboard cleanly with CORRECT names matching data module
