                  <XAxis dataKey="band" tick={{ fontSize: 11, fill: "#64748b" }} />
                  <YAxis domain={[1.2, 1.7]} tick={{ fontSize: 11, fill: "#64748b" }} />
                  <Tooltip />
                  <Bar dataKey="meanTfr" name="Mean TFR" radius={[6, 6, 0, 0]}>
                    {bandBars.map((b) => (
                      <Cell
