import fs from "node:fs";

const s = fs.readFileSync("src/data/posts.ts", "utf8");
console.log("file MB", (s.length / 1e6).toFixed(2));
console.log(
  "oecd count",
  (s.match(/oecd-childcare-costs-versus-total-fertility-2026/g) || []).length,
);
const i = s.indexOf('id: "oecd-childcare-costs-versus-total-fertility-2026"');
const j = s.indexOf('id: "us-atc-delay-minutes-by-cause-2026"');
console.log({ oecdAt: i, atcIdAt: j });
const cstart = s.indexOf("content: `", i);
console.log("snippet after content:", JSON.stringify(s.slice(cstart, cstart + 120)));
// Find end of first post by looking for pattern `,\n  },\n  {\n    id:
const re = /`,\n  \},\n  \{\n    id: "/g;
re.lastIndex = cstart;
const m = re.exec(s);
console.log("first closed content at", m?.index, "next id", m?.[0].slice(0, 40));
// Count how many top-level post ids
const ids = [...s.matchAll(/^\s{4}id: "([^"]+)"/gm)].map((x) => x[1]);
console.log("top-level ids", ids.length, ids.slice(0, 5));

